/**
     * An utility method for calling {@link KeyAnalyzer#compare(Object, Object)}
     */

method_definition:
final boolean compareKeys(final K key, final K other) {
        if (key == null) {
            return other == null;
        } else if (other == null) {
            return false;
        }

        return keyAnalyzer.compare(key, other) == 0;
    }

